import{_ as t,c as a,o as i,j as n,Y as r,t as s}from"./chunks/framework.BNTND4LZ.js";const g=JSON.parse('{"title":"protocols | x-cmd man (man5) | protocols definition file","titleTemplate":false,"description":"x-cmd man (man5 Manual Page) | protocols - protocols definition file","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"protocols | x-cmd man (man5) | protocols definition file"}],["meta",{"name":"og:description","content":"x-cmd man (man5 Manual Page) | protocols - protocols definition file"}]]},"headers":[],"params":{"isMan":true,"man":"protocols","category":"man5","desc":"protocols definition file"},"relativePath":"man5/protocols.md","filePath":"man5/[man].md"}'),l={name:"man5/protocols.md"},d={class:"visually-hidden"};function c(o,e,p,m,h,f){return i(),a("div",null,[n("h1",d,s(o.$params.man),1),e[0]||(e[0]=r('<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>protocols - protocols definition file</p><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>This file is a plain ASCII file, describing the various DARPA internet protocols that are available from the TCP/IP subsystem. It should be consulted instead of using the numbers in the ARPA include files, or, even worse, just guessing them. These numbers will occur in the protocol field of any IP header.</p><p>Keep this file untouched since changes would result in incorrect IP packages. Protocol numbers and names are specified by the IANA (Internet Assigned Numbers Authority).</p><p>Each line is of the following format:</p><blockquote><p><em>protocol number aliases ...</em></p></blockquote><p>where the fields are delimited by spaces or tabs. Empty lines are ignored. If a line contains a hash mark (#), the hash mark and the part of the line following it are ignored.</p><p>The field descriptions are:</p><dl><dt><em>protocol</em></dt><dd>the native name for the protocol. For example <em>ip</em>, <em>tcp</em>, or <em>udp</em>.</dd><dt><em>number</em></dt><dd>the official number for this protocol as it will appear within the IP header.</dd><dt><em>aliases</em></dt><dd>optional aliases for the protocol.</dd></dl><p>This file might be distributed over a network using a network-wide naming service like Yellow Pages/NIS or BIND/Hesiod.</p><h2 id="files" tabindex="-1">FILES <a class="header-anchor" href="#files" aria-label="Permalink to &quot;FILES&quot;">​</a></h2><dl><dt><em>/etc/protocols</em></dt><dd>The protocols definition file.</dd></dl><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p><strong>getprotoent</strong>(3)</p><p><a href="http://www.iana.org/assignments/protocol-numbers" target="_blank" rel="noreferrer"></a></p>',16))])}const b=t(l,[["render",c]]);export{g as __pageData,b as default};
